def pick(c):
    for s in c["sources"]:
        if s["kind"] not in ("x-post", "instagram") and s["tier"] in ("T1", "T2", "T3") and s["link_status"] == "ok" and s["url"].startswith("http"): return s
def sid(s):
    a, _, b = s["id"].partition("_"); outlet = {"uh": "ultimahora", "ln": "lanacion", "elnac": "elnacional", "5d": "5dias", "obs": "elobservador", "muni": "asuncion-gov", "dip3245": "diputados", "cp": "cp", "ind": "elindependiente", "mil": "radio1000"}.get(a, a)
    return "src:%s-%s-%s" % (outlet, s["pub_date"], re.sub(r"[^a-z0-9]+", "-", (b or a).lower()).strip("-"))
def cut(t, n=700):
    if len(t) <= n: return t
    t = t[:n]; i = max(t.rfind(". "), t.rfind("; "))
    return (t[:i + 1] if i > 300 else t.rstrip() + " [...]")
def quote(q):
    q = re.sub(r"\s*\(.*?\)\s*$", "", q).strip("«»“”\"' "); w = q.split()
    return " ".join(w[:12]) if q else ""
def prov(cid, who, s, q=""):
    return {"asserted_by": who, "source": sid(s), "locator": "official page" if s["kind"].startswith("official") else "article",
            "quote": q, "confidence": "medium", "note": "Link from the 24 Nov 2026 dossiers (v1.8, v1.9), marked ok by its checker on %s. Not opened by this project. Dossier claim %s, labelled %s / %s." % (s.get("retrieved", "?"), cid, CL[cid]["label"], CL[cid]["status"])}
srcs, events, facts, skipped = {}, [], [], dict(SKIP)
for cid, (cat, who, ten, tes, parties, amt, cur, over) in M.items():
    c = CL[cid]; s = pick(c)
    assert s, cid
    srcs[sid(s)] = {"id": sid(s), "kind": "official" if s["kind"].startswith("official") else "press", "outlet": re.sub(r"\s*\(PY\)", "", s["outlet"]), "title": s["title"], "date": s["pub_date"], "url": s["url"], "page": "dossier v1.9 source id %s" % s["id"]}
    events.append({"id": "dos6:event:%04d" % (len(events) + 1), "date": c["event_date"], "date_precision": {4: "year", 7: "month"}.get(len(c["event_date"]), "day"), "category": cat,
                   "title_en": ten, "title_es": tes, "detail_en": over or cut(c["statement"]), "detail_es": tes + ". (Detalle completo solo en inglés.)", "parties": parties, "amount": amt, "currency": cur,
                   "prov": prov(cid, who, s, "" if over else quote(c.get("quote", "")))})
srcs, events, facts = srcs, events, facts
for cid, dsid, date, cat, who, ten, tes, parties, det in EXTRA:
    s = next(x for x in CL[cid]["sources"] if x["id"] == dsid)
    assert s["link_status"] == "ok" and s["kind"] == "article", dsid
    srcs[sid(s)] = {"id": sid(s), "kind": "press", "outlet": re.sub(r"\s*\(PY\)", "", s["outlet"]), "title": s["title"], "date": s["pub_date"], "url": s["url"], "page": "dossier v1.9 source id %s" % s["id"]}
    pr = prov(cid, who, s); pr["confidence"] = "medium"
    events.append({"id": "dos6:event:%04d" % (len(events) + 1), "date": date, "date_precision": {4: "year", 7: "month"}.get(len(date), "day"), "category": cat, "title_en": ten, "title_es": tes, "detail_en": det,
                   "detail_es": tes + ". (Detalle completo solo en inglés.)", "parties": parties, "amount": None, "currency": None, "prov": pr})
for i, (cid, ent, metric, val, cur, note, period) in enumerate(FACTS, 1):
    s = pick(CL[cid]); who = M[cid][1]
    facts.append({"id": "dos6:fact:%04d" % i, "entity": ent, "metric": metric, "value": val, "currency": cur, "unit_note": note, "period": period, "prov": prov(cid, who, s)})
def dump(kind, rows):
    with open(os.path.join(RAW, "dos6.%s.jsonl" % kind), "w", encoding="utf-8") as f:
        for r in rows: f.write(json.dumps(r, ensure_ascii=False) + "\n")
dump("sources", sorted(srcs.values(), key=lambda r: r["id"])); dump("events", events); dump("facts", facts)
seen = open("/dev/null"); new_ids = [c["id"] for c in D["claims"] if c["id"] not in M and c["id"] not in SKIP]
print(len(srcs), "sources,", len(events), "events,", len(facts), "facts; skipped on purpose:", len(SKIP))
